/** E-Mail-Versand je Mandant: SMTP-Zugang (Anbieter-Voreinstellungen), Absender, Tageslimit, optional IMAP für Antworten. */
export const mailSettings = mysqlTable("mailSettings", { id: int("id").autoincrement().primaryKey(), tenantId: int("tenantId").notNull(), provider: varchar("provider", { length: 32 }).default("smtp").notNull(), host: varchar("host", { length: 200 }), port: int("port").default(587), secure: boolean("secure").default(false).notNull(), username: varchar("username", { length: 320 }), password: text("password"), fromName: varchar("fromName", { length: 120 }), fromEmail: varchar("fromEmail", { length: 320 }), replyTo: varchar("replyTo", { length: 320 }), dailyLimit: int("dailyLimit").default(300).notNull(), enabled: boolean("enabled").default(false).notNull(), imapEnabled: boolean("imapEnabled").default(false).notNull(), imapHost: varchar("imapHost", { length: 200 }), imapPort: int("imapPort").default(993), imapUsername: varchar("imapUsername", { length: 320 }), imapPassword: text("imapPassword"), lastTestAt: timestamp("lastTestAt"), lastTestStatus: varchar("lastTestStatus", { length: 40 }), lastError: text("lastError"), replyAiEnabled: boolean("replyAiEnabled").default(true).notNull(), replyAiAutoBlock: boolean("replyAiAutoBlock").default(true).notNull(), replyAiInterest: boolean("replyAiInterest").default(true).notNull(), imapScope: varchar("imapScope", { length: 16 }).default("bekannte").notNull(), lastReplyCheckAt: timestamp("lastReplyCheckAt"), createdAt: timestamp("createdAt").defaultNow().notNull(), updatedAt: timestamp("updatedAt").defaultNow().onUpdateNow().notNull() }, (t) => [uniqueIndex("mail_settings_tenant_unique").on(t.tenantId)]);


/** Posteingang: per IMAP abgeholte Mails (Antworten auf Kampagnen und sonstige), verknüpft mit Empfänger/Lead. */
export const inboxMessages = mysqlTable("inboxMessages", { id: int("id").autoincrement().primaryKey(), tenantId: int("tenantId").notNull(), messageId: varchar("messageId", { length: 320 }).notNull(), imapUid: int("imapUid"), fromEmail: varchar("fromEmail", { length: 320 }).notNull(), fromName: varchar("fromName", { length: 200 }), subject: varchar("subject", { length: 400 }), bodyText: text("bodyText"), receivedAt: timestamp("receivedAt").notNull(), isRead: boolean("isRead").default(false).notNull(), campaignRecipientId: int("campaignRecipientId"), leadId: int("leadId"), archived: boolean("archived").default(false).notNull(), blocked: boolean("blocked").default(false).notNull(), optOut: boolean("optOut").default(false).notNull(), aiKind: varchar("aiKind", { length: 20 }), aiConfidence: int("aiConfidence"), aiQuote: varchar("aiQuote", { length: 300 }), aiReason: varchar("aiReason", { length: 200 }), aiSource: varchar("aiSource", { length: 10 }), aiAction: varchar("aiAction", { length: 20 }), createdAt: timestamp("createdAt").defaultNow().notNull() }, (t) => [index("inbox_tenant_idx").on(t.tenantId, t.receivedAt), uniqueIndex("inbox_message_unique").on(t.tenantId, t.messageId)]);
export type InboxMessage = typeof inboxMessages.$inferSelect;

/** Notizen an Pipeline-Karten (Text oder per Spracheingabe diktiert). */
export const pipelineNotes = mysqlTable("pipelineNotes", { id: int("id").autoincrement().primaryKey(), tenantId: int("tenantId").notNull(), leadId: int("leadId").notNull(), authorUserId: int("authorUserId"), text: text("text").notNull(), source: mysqlEnum("source", ["text", "sprache", "gespraech"]).default("text").notNull(), dialerCallId: int("dialerCallId"), createdAt: timestamp("createdAt").defaultNow().notNull() }, (t) => [index("pipeline_notes_lead_idx").on(t.tenantId, t.leadId)]);

/** Vertriebspipeline: je Mandant anpassbare Stufen (Reihenfolge, Namen, Hinweise). */
export const pipelineStageConfigs = mysqlTable("pipelineStageConfigs", { id: int("id").autoincrement().primaryKey(), tenantId: int("tenantId").notNull(), source: varchar("source", { length: 16 }).default("alle").notNull(), stages: json("stages").notNull(), updatedAt: timestamp("updatedAt").defaultNow().onUpdateNow().notNull() }, (t) => [uniqueIndex("pipeline_stage_configs_tenant_source_unique").on(t.tenantId, t.source)]);

/** Lead-Finder: gefundene Firmen (Suche im Internet, regional) mit Profil – bis sie in die Pipeline übernommen werden. */
export const companyProspects = mysqlTable("companyProspects", { id: int("id").autoincrement().primaryKey(), tenantId: int("tenantId").notNull(), query: varchar("query", { length: 160 }), location: varchar("location", { length: 160 }), name: varchar("name", { length: 200 }).notNull(), website: varchar("website", { length: 400 }), email: varchar("email", { length: 320 }), phone: varchar("phone", { length: 48 }), street: varchar("street", { length: 200 }), postcode: varchar("postcode", { length: 24 }), city: varchar("city", { length: 120 }), lat: decimal("lat", { precision: 9, scale: 6 }), lng: decimal("lng", { precision: 9, scale: 6 }), source: varchar("source", { length: 32 }).notNull(), externalId: varchar("externalId", { length: 160 }), rating: decimal("rating", { precision: 3, scale: 1 }), ratingCount: int("ratingCount"), profile: json("profile"), enrichedAt: timestamp("enrichedAt"), status: mysqlEnum("status", ["neu", "uebernommen", "ignoriert"]).default("neu").notNull(), leadId: int("leadId"), createdAt: timestamp("createdAt").defaultNow().notNull() }, (t) => [index("prospects_tenant_idx").on(t.tenantId, t.createdAt), uniqueIndex("prospects_external_unique").on(t.tenantId, t.source, t.externalId)]);
export type CompanyProspect = typeof companyProspects.$inferSelect;

/** Wiedervorlagen & Aufgaben an Pipeline-Karten („Heute fällig“): Anruf, E-Mail, Termin, Aufgabe, SMS, WhatsApp – mit Fälligkeit und Zuständigem. */
export const pipelineTasks = mysqlTable("pipelineTasks", { id: int("id").autoincrement().primaryKey(), tenantId: int("tenantId").notNull(), leadId: int("leadId").notNull(), ownerUserId: int("ownerUserId"), kind: mysqlEnum("kind", ["anruf", "email", "termin", "aufgabe", "sms", "whatsapp"]).default("anruf").notNull(), title: varchar("title", { length: 200 }).notNull(), note: varchar("note", { length: 600 }), dueAt: timestamp("dueAt").notNull(), doneAt: timestamp("doneAt"), source: mysqlEnum("source", ["manuell", "dialer", "notiz", "automatik", "termin"]).default("manuell").notNull(), createdByUserId: int("createdByUserId"), createdAt: timestamp("createdAt").defaultNow().notNull(), updatedAt: timestamp("updatedAt").defaultNow().onUpdateNow().notNull() }, (t) => [index("pipeline_tasks_due_idx").on(t.tenantId, t.doneAt, t.dueAt), index("pipeline_tasks_lead_idx").on(t.tenantId, t.leadId)]);
export type PipelineTask = typeof pipelineTasks.$inferSelect;

/** Pipeline-Automatik je Mandant: eingeschlafene Karten, Stufe/Anruf-Ergebnis → E-Mail-Serie, Antwort → Stufe, Terminerinnerung, Verteilregeln, Tagesziele (JSON, siehe shared/pipeline-extras.ts). */
export const pipelineSettings = mysqlTable("pipelineSettings", { id: int("id").autoincrement().primaryKey(), tenantId: int("tenantId").notNull(), settings: json("settings").notNull(), distributionCursor: int("distributionCursor").default(0).notNull(), updatedAt: timestamp("updatedAt").defaultNow().onUpdateNow().notNull() }, (t) => [uniqueIndex("pipeline_settings_tenant_unique").on(t.tenantId)]);

/** Einzelne Nachrichten aus der Pipeline-Karte (SMS, WhatsApp, E-Mail) und automatische Terminerinnerungen – mit Versandstatus. */
export const outboundMessages = mysqlTable("outboundMessages", { id: int("id").autoincrement().primaryKey(), tenantId: int("tenantId").notNull(), leadId: int("leadId"), channel: mysqlEnum("channel", ["sms", "whatsapp", "email"]).notNull(), toAddress: varchar("toAddress", { length: 320 }).notNull(), subject: varchar("subject", { length: 320 }), text: text("text").notNull(), templateKey: varchar("templateKey", { length: 60 }), status: mysqlEnum("status", ["gesendet", "simuliert", "fehlgeschlagen", "link"]).notNull(), provider: varchar("provider", { length: 40 }), providerSid: varchar("providerSid", { length: 80 }), error: varchar("error", { length: 400 }), inboxMessageId: int("inboxMessageId"), createdByUserId: int("createdByUserId"), createdAt: timestamp("createdAt").defaultNow().notNull() }, (t) => [index("outbound_messages_lead_idx").on(t.tenantId, t.leadId), index("outbound_messages_to_idx").on(t.tenantId, t.toAddress)]);

/** Sperrliste für E-Mail-Kampagnen: Bounces, Beschwerden, Abmeldungen, Handsperren – diese Adressen werden nie wieder angeschrieben. */
export const emailSuppressions = mysqlTable("emailSuppressions", { id: int("id").autoincrement().primaryKey(), tenantId: int("tenantId").notNull(), email: varchar("email", { length: 320 }).notNull(), reason: mysqlEnum("reason", ["bounce", "beschwerde", "abgemeldet", "gesperrt", "manuell"]).notNull(), note: varchar("note", { length: 400 }), source: varchar("source", { length: 160 }), createdAt: timestamp("createdAt").defaultNow().notNull() }, (t) => [uniqueIndex("email_suppressions_unique").on(t.tenantId, t.email)]);
